class Solution {
    public int distinctPrimeFactors(int[] nums){
        Set<Integer> factors=new HashSet<>();
        for(int input:nums){
            int value=input;
            for(int divisor=2;divisor*divisor<=value;divisor++)if(value%divisor==0){
                factors.add(divisor);
                while(value%divisor==0)value/=divisor;
            }
            if(value>1)factors.add(value);
        }
        return factors.size();
    }
}

code.kotlin:
class Solution {
    fun distinctPrimeFactors(nums:IntArray):Int{
        val factors=HashSet<Int>();
        for(input in nums){
            var value=input;
            var divisor=2;
            while(divisor*divisor<=value){
                if(value%divisor==0){
                    factors.add(divisor);
                    while(value%divisor==0)value/=divisor
                };
                divisor++
            };
            if(value>1)factors.add(value)
        };
        return factors.size
    }
}

